import * as cdk from 'aws-cdk-lib';
import * as budgets from 'aws-cdk-lib/aws-budgets';
class BudgetStack extends cdk.Stack {
  constructor(scope, id, props) { super(scope, id, props);
    new budgets.CfnBudget(this, 'StagingBudget', {
